INSERT INTO task_pool (task_name, prompt, category, instance_target, priority, estimated_minutes) VALUES
('pool-hydrator', 'Keep the BASTION pool at >=12 waiting tasks focused on self-hosted/bare-metal sovereignty for a solo operator. Principle: self-host what benefits from sovereignty/high-IO; keep edge+global on Cloudflare (hybrid). Never expose raw ports — tunnel everything. Check depth: SELECT COUNT(*) FROM task_pool WHERE instance_target=''bastion'' AND status=''waiting''. If <12, generate 8 specific IMPLEMENTATION tasks (harden/migrate/back-up/monitor). Priority 20-60. Insert, re-queue yourself priority 1, log pool.hydrated.', 'meta', 'bastion', 1, 8);

-- TASK POOL (9 tasks)
INSERT INTO task_pool (task_name, prompt, category, instance_target, priority, estimated_minutes) VALUES
('reverse-proxy-local-dns', 'Stand up the 2026-standard secure local routing: an internal reverse proxy (Caddy/Traefik/nginx) plus a local DNS resolver, instead of router port-forwarding. Internal services get names + TLS via the proxy; nothing is exposed by opening router ports. Document the proxy config, the local DNS zone, and the routing map.', 'network', 'bastion', 20, 30),
('docker-ufw-bypass-fix', 'Close the Docker/UFW bypass flaw: Docker manipulates iptables and punches through UFW, so a port blocked in UFW but published by Docker is still exposed. Fix: bind sensitive container ports to 127.0.0.1 explicitly, use the reverse proxy for the only public surface, and add DOCKER-USER iptables rules to enforce host firewall intent. Verify with a port scan from another host. Document the rules.', 'security', 'bastion', 22, 25),
('cloudflare-tunnel-no-open-ports', 'Expose self-hosted services ONLY via Cloudflare Tunnel (cloudflared) — zero inbound ports open on the router/firewall. Install cloudflared, create a named tunnel, map hostnames to internal proxy targets, put Cloudflare Access in front for auth. Confirm the box has no open inbound ports from the public internet. Document the tunnel config and Access policies.', 'network', 'bastion', 24, 25),
('nextcloud-nvme', 'Deploy Nextcloud on bare-metal NVMe as the sovereign Drive/Workspace complement (NVMe eliminates the usual PHP sluggishness). Containerized, behind the reverse proxy, exposed only via the tunnel. Enable server-side encryption, 2FA, and external storage to R2 if useful. This holds the data you want fully under your control. Document the deploy and backup hooks.', 'selfhost', 'bastion', 30, 30),
('hybrid-architecture-split', 'Document the hybrid split explicitly: what runs on bare metal (high-IO databases, sensitive/sovereign data, heavy local compute) vs what stays on Cloudflare edge (global delivery, workers, R2, D1, DNS). Give a decision rule for placing any new workload. This is the ''to a logical degree'' boundary — write it down so it''s consistent. Output an architecture doc + diagram.', 'architecture', 'bastion', 26, 20),
('backups-3-2-1', 'Implement 3-2-1 backups for all self-hosted data (3 copies, 2 media, 1 offsite): local snapshot, second local/media copy, offsite encrypted to R2 (or B2). Automate with restic/borg, encrypt at rest, schedule, and — critically — TEST restores (a backup you haven''t restored is a hope, not a backup). Document the schedule, encryption keys location, and a verified restore run.', 'resilience', 'bastion', 32, 28),
('host-monitoring-ids', 'Set up host monitoring + intrusion detection + log aggregation on the bare-metal box: metrics (node exporter + a dashboard), IDS (CrowdSec or fail2ban + auditd), and centralized logs. Alert to the Slack #cannon-ops channel via RELAY''s incoming webhook. Document what''s watched and the alert routes.', 'observability', 'bastion', 34, 25),
('os-baseline-hardening', 'Baseline-harden the host OS (Debian/Ubuntu): SSH key-only + no root login + non-standard exposure only via tunnel, automatic security updates, minimal package surface, UFW default-deny (with the Docker fix from the ufw task), disk encryption (LUKS) if the box is physically reachable, and a CIS-style checklist pass. Document the applied baseline.', 'security', 'bastion', 28, 25),
('secrets-vault-selfhosted', 'Run a self-hosted secrets vault (Infisical/Vault/OpenBao) on the bastion for local service credentials, sealed and backed up, accessible only via the internal network/tunnel. Bridge to Cloudflare secrets where workers need the same value. Coordinate with FORTRESS/CONDUIT secret inventories to keep one source of truth. Document the vault topology and unseal procedure.', 'secrets', 'bastion', 38, 22);

